// apply-halaman4.mjs — Halaman jadwal + fix OC/Certificate + tautan unduh dokumen.
//   (1) /jadwal-kereta-api & /jadwal-penerbangan (dari tmjadwalka/tmjadwalpn).
//   (2) OC dipisah dari sistem Certificate → /oc jadi accordion (Certificate + Operating Certificate).
//   (3) Tautan UNDUH di OC, JDQ, Online Publication → /dokumen/<file> (taruh file di static/dokumen/).
// PRASYARAT: jalankan SETELAH apply-dinamis..apply-halaman3 (script ke-1 s/d 7).
// Cara pakai (dari root project):
//     node apply-halaman4.mjs
//     npm run dev     (WAJIB restart penuh — ada route baru)
// Aman dijalankan berkali-kali.

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const FILES = [
  ["src/lib/server/db/schema.ts", ''],
  ["src/lib/types/content.ts", ''],
  ["src/lib/server/portal/queries.ts", ''],
  ["src/lib/data/nav.ts", ''],
  ["src/lib/utils.ts", ''],
  ["src/lib/data/stasiun.ts", ''],
  ["src/routes/oc/+page.server.ts", ''],
  ["src/routes/oc/+page.svelte", ''],
  ["src/routes/online-publication/+page.svelte", ''],
  ["src/routes/jdq/+page.svelte", ''],
  ["src/routes/jadwal-kereta-api/+page.server.ts", ''],
  ["src/routes/jadwal-kereta-api/+page.svelte", ''],
  ["src/routes/jadwal-penerbangan/+page.server.ts", ''],
  ["src/routes/jadwal-penerbangan/+page.svelte", ''],
];

let ok = 0;
for (const [path, b64] of FILES) {
  try {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, Buffer.from(b64, 'base64'));
    console.log('  ditulis:', path);
    ok++;
  } catch (e) {
    console.error('  GAGAL  :', path, '-', e.message);
  }
}
console.log('\nSelesai. ' + ok + '/' + FILES.length + ' file ditulis. SEMUA menu navbar kini aktif (0 "Segera").');
console.log('Restart dev server (WAJIB): npm run dev');
console.log('Halaman baru: /jadwal-kereta-api & /jadwal-penerbangan.');
console.log('OC (/oc) kini accordion terpisah dari sistem Certificate (/certificate).');
console.log('UNDUH dokumen: taruh berkas di  static/dokumen/  → tautan otomatis jalan (tanpa route tambahan).');
console.log('Peta kode stasiun/kota bisa dilengkapi di  src/lib/data/stasiun.ts');
